group(C,'recordUnexpectedFailure','Attempts to persist a bounded unexpected-worker error for the affected submission IDs while preserving accepted/applied evidence.')
group(C,'processLeadIds','Reloads and orders submissions, matches exact normalised references, rejects missing/ambiguous/invalid targets, validates each update and merges valid changes per booking. Saves booking plus applied audit atomically, sends receipts separately and deletes eligible successful temporary Leads.')
