group(C,'nonBlankLineCount','Counts nonempty roster lines; the count must match the declared allocation.')
group(C,'applyHeavyFields','Replaces the heavy item/haulier/delivery/contact fields from a complete valid submission and marks heavy details provided; stale optional fields are explicitly cleared.')
group(C,'applyLogoFields','Idempotently sets logo-provided state/time while retaining previous completion evidence on repeat declarations.')
group(C,'isValidBookingReference','Checks the normalised NTE reference grammar used for the exact booking match.')
group(C,'acknowledgementTemplate','Selects the exhibitor staff, partner staff or heavy-vehicle receipt developer name. Logo updates do not request an acknowledgement email.')
group(C,'appliedBookingId','Reads the durable booking identity captured when the submission was applied; a current reference alone cannot manufacture that identity.')
group(C,'matchesAppliedBooking','Requires the saved applied identity/reference to agree with the booking before any receipt retry.')
group(C,'acknowledgementAudit','Builds the source Lead receipt acceptance/failure/timestamp update.')
group(C,'acknowledgementMessage','Builds the stored Lead-template receipt addressed to the matched booking Primary Contact, while using the preserved submission as merge context.')
group(C,'sendAcknowledgements','Loads templates and exact Primary Contacts in bulk, sends bounded receipt groups and maps outcomes per Lead. More than 100 receipts returns failure/retry guidance without undoing applied booking data.')
group(C,'retryAcknowledgement','User action retries only one failed receipt after verifying its applied booking and current Primary Contact. Does not replay booking field updates, rematch to another record or delete the source Lead.')
group(C,'templateIds','Maps the requested stored template developer names to Salesforce EmailTemplate IDs.')

C='NTERelatedOpportunityController'
group(C,'RelatedOpportunity','Projects the readable Opportunity into display fields, including event, reference, stage, amount and whether the current Contact role is Primary.')
group(C,'RelatedAccount','Projects the linked Account into its display name and record link.')
group(C,'RelatedContact','Projects a Contact Role into Contact details, role and Primary indicator.')
