group(C,'typeLabel typeIcon','Maps the supported form type to the participant label or icon used in panel rows.')
group(C,'leadStage','Presents recorded Converted, Rejected, Invited, Queued or current review state without reopening a decided Lead.')
group(C,'preferredContact','Combines the saved preferred contact method and timing for the detail panel.')
group(C,'leadViewClause','Adds the exact interest/application/guest/recent Lead filter for a normalised queue key.')
group(C,'activeInterestClause','Excludes converted, progressed and not-progressed interests from active review.')
group(C,'activeApplicationClause','Excludes converted and rejected applications from active review.')
group(C,'opportunityViewClause','Selects the quote/invoice/payment, preparation, completed or approved booking subset for the chosen view.')
group(C,'logisticsOutstandingClause','Expresses unresolved heavy-vehicle state in SOQL, including unknown answers rather than assuming No.')
group(C,'completeClause','SOQL counterpart of isComplete, used by counts and final-pack/completed selection. Must stay aligned with the in-memory rule.')
group(C,'billableClause baseBillableClause topUpBillableClause','Returns the SOQL predicate for any, base or separate top-up charge respectively.')
group(C,'pricingReadyClause pricingReviewClause','Returns the SOQL known-price or review-required predicate used consistently in finance queues.')
group(C,'anyInvoiceOutstandingClause','Selects bookings with an unresolved applicable base or top-up invoice.')
group(C,'allInvoicesProvidedClause','Requires both applicable invoices or known non-billable exceptions.')
group(C,'actionablePaymentClause','Selects a payment that can be recorded now, respecting quote, invoice and booking-first order while allowing independent top-up invoice work.')
group(C,'allPaymentsReceivedClause','Requires both applicable base and top-up payments, allowing known non-billable charges to pass.')
group(C,'quoteResolvedClause','Accepts no quote requirement or a saved provided quote.')
group(C,'notBillableClause baseNotBillableClause topUpNotBillableClause','Returns the complementary known non-billable predicates for combined, base or top-up finance. Unknown pricing is not equivalent to free.')
group(C,'viewCount','Returns the count associated with a normalised view key.')
group(C,'configurePagination','Clamps page size/offset to a valid accessible last page and the 2000-row browser cap, even when queues shrink between requests.')
group(C,'countLead countOpportunity','Executes the named object bound aggregate count in USER_MODE.')
group(C,'leadBaseWhere','Builds the supported NTE Lead/event/owner/creation-date base predicate.')
group(C,'opportunityBaseWhere','Builds the NTE record type, supported participant, nonblank event, open-or-won, owner and creation-date base predicate.')
group(C,'baseBinds','Produces bind variables for event, owner, time and required record type/form choices.')
group(C,'copyBindsWith','Copies a query bind map before adding a view-specific parameter.')
group(C,'eventOptions','Collects nonblank event codes from relevant main Leads/bookings and sorts them descending. Legacy codes remain selectable; unrelated/supplementary-only events do not become empty choices.')
group(C,'ownerOptions','Returns selectable owner label/ID options for the dashboard scope.')
group(C,'reportUrls','Resolves the stored NTE report IDs and builds native Lightning URLs, including the weekly finance report.')
group(C,'resolveEventCode','Preserves an explicit available edition; otherwise selects the highest available canonical NTE plus four-digit year, then falls back to the first option only if no canonical code exists.')
group(C,'communicationEventCode','Strictly validates a communication edition rather than silently substituting another when a draft action is stale.')
group(C,'normalizeTimeRange','Normalises dashboard time-range input to the supported choices.')
group(C,'communicationTimeRange','Rejects unsupported/stale communication time ranges instead of widening the intended recipient scope.')
group(C,'normalizeViewKey','Maps aliases and supported panel view keys to the canonical queue; falls back only for ordinary dashboard navigation.')
group(C,'normalizeOwnerId','Validates the selected owner ID or recognised all-owner choice before binding the query.')
group(C,'normalizeReminderView','Restricts the retained reminder API to the supported outstanding preparation views.')
group(C,'reminderBookings','Loads up to 2000 scoped candidate bookings for the retained legacy reminder draft, ordered by Account/name.')
group(C,'primaryContactsByOpportunity','Delegates exact Primary Contact resolution for the selected reminder bookings.')
group(C,'reminderTitle reminderSubject reminderBody','Supplies legacy kind-specific reminder presentation text; the active composer defaults are in NTEEmailDispatchService.')
group(C,'reminderUrl','Resolves the legacy reminder form destination from view, participant type and routing metadata.')
group(C,'personaliseReminder','Expands the retained legacy reminder body against one recipient snapshot.')
group(C,'reminderAuditTask','Builds the historical reminder audit Task shape. The retired send entry point cannot dispatch through this path.')
group(C,'closedTaskStatus','Finds a usable closed Task status for audit creation rather than assuming a target-specific label.')
group(C,'sinceAt','Converts the supported time-range choice into a CreatedDate lower-bound timestamp; all time has no lower bound.')
group(C,'safeMessage','Returns bounded useful exception text for the operator without replacing a specific controlled validation message.')
group(C,'handled','Creates an AuraHandledException for a controlled Lightning-visible error.')

group('NTEVat','rate','Uses the saved VAT rate where populated, otherwise the generated 20% policy rate.')
group('NTEVat','tax','Returns null for unknown net amounts, otherwise rounds net times rate to two decimal places using HALF_UP.')
group('NTEVat','gross','Adds the separately calculated aggregate VAT to the net charge, preserving null for unknown prices.')
group('NTEStripeClient','vatMessage','Formats the saved net subtotal, aggregate VAT and gross payable total for the checkout disclosure.')
